from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _gmm_kernel(lhs_ref, rhs_ref, out_ref, acc_ref, *, group_size):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    lhs = lhs_ref[...].astype(jnp.float32)
    rhs = rhs_ref[...].astype(jnp.float32)
    acc_ref[...] += jax.lax.dot(
        lhs, rhs, preferred_element_type=jnp.float32
    )

    @pl.when(k == pl.num_programs(2) - 1)
    def _store():
        out_ref[...] = acc_ref[...].astype(out_ref.dtype)


def workload(lhs, rhs, group_sizes, max_expert_size):
    g, k_size, n = rhs.shape
    m = lhs.shape[0]
    k = lhs.shape[1]

    bm = 512
    bk = 512
    bn = 512
    bk_steps = k // bk

    # Each group is a contiguous block of the flattened LHS.
    lhs_grouped = lhs.reshape((g, m, k))

    def lhs_map(g_idx, m_idx, k_idx):
        return (g_idx, m_idx, k_idx)

    def rhs_map(g_idx, m_idx, k_idx):
        return (g_idx, 0, 0)

    def out_map(g_idx, m_idx, k_idx):
        return (g_idx, m_idx, 0)

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(g, m // bm, k_steps),
        in_specs=[
            pl.BlockSpec((1, bm, bk), lhs_map),
            pl.BlockSpec((1, k_size, bn), rhs_map),
        ],
        out_specs=pl.BlockSpec((1, bm, bn), out_map),
        scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
    )

    result = pl.pallas_call(
        lambda l, r, o, a: _gmm_kernel(l, r, o, a, group_size=bm),
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct((g, m, n), lhs.dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(lhs_grouped, rhs)

    return result.reshape((m, n))
