    acc_ref[...] += jax.lax.dot(
        q_ref[...],
        k_ref[...],
        preferred_element_type=jnp.float32,
        dimension_numbers=(((1,), (1,)), ((), ())),
    )

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        score = acc_ref[...] * jnp.float32(1.0 / jnp.sqrt(jnp.float32(q_ref.shape[3])))
        score += bias_ref[...].astype(jnp.float32)
        out_ref[...] = score.astype(out_ref.dtype)


def _attention_kernel(attn_ref, v_ref, out_ref, acc_ref):
    k = pl.program_id(2)

