from jax.experimental.pallas import tpu as pltpu


def _grouped_matmul_kernel(x_ref, weights_ref, out_ref):
    x = x_ref[0, :, :]
    weights = weights_ref[0, :, :]
    out_ref[0, :, :] = jnp.dot(
        x, weights, preferred_element_type=jnp.float32
    ).astype(out_ref.dtype)


def workload(x, weights):
    g, m_per_group, k = x.shape
    n = weights.shape[2]
    m = g * m_per_group

    bm = 512
    while bm > 8 and m % bm != 0:
        bm //= 2
    if m % bm != 0:
        bm = m

    x_grouped = x.reshape(g, m, k)
    weights_grouped = weights.reshape(g, k, n)

    def x_map(group, row):
        return (group, row, 0)

    def weights_map(group, row):
        del row
        return (group, 0, 0)

    def out_map(group, row):
        return (group, row, 0)

    return pl.pallas_call(
        _grouped_matmul_kernel,
        out_shape=jax.ShapeDtypeStruct((g, m, n), x.dtype),
        grid=(g, m // bm),
        in_specs=[
            pl.BlockSpec((1, bm, k), x_map),
            pl.BlockSpec((1, k, n), weights_map),
        ],
        out_specs=pl.BlockSpec((1, bm, n), out_map),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(x_grouped, weights_grouped)
